#include <iostream>
#include <sstream>
#include <string>

int main() {
    std::istringstream entrada{"  rio\tmonte\nvalle  "};
    std::string palabra;
    int cantidad = 0;
    while (entrada >> palabra) {
        std::cout << "<" << palabra << ">\n";
        ++cantidad;
    }
    std::cout << "Palabras: " << cantidad;
    return 0;
}

