#include <iostream>
#include <sstream>
#include <string>

void probar(const std::string& texto) {
    std::istringstream entrada{texto};
    std::string palabra;
    int cantidad = 0;
    while (entrada >> palabra) {
        std::cout << "<" << palabra << ">\n";
        ++cantidad;
    }
    std::cout << "Palabras: " << cantidad;
    std::cout << "\n";
}

int main() {
    probar("  eco\tmar\nsol  ");
    probar("");
    probar("   ");
    probar("una dos");
    probar("unodos");
    probar("  ola  ");
    return 0;
}
